const safeLink=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}};
const profileAvatar=t=>t.pfp?`<img src="${esc(t.pfp)}" alt="${esc(t.name)} profile picture">`:esc(t.symbol);
const cardUnits=n=>n>0&&n<1?n.toLocaleString(undefined,{maximumFractionDigits:6}):fmt(n);
const mintAge=t=>{if(!t.mintedAt)return t.mint?'Confirmed':'Not minted';const mins=Math.max(0,Math.floor((Date.now()-Date.parse(t.mintedAt))/60000));return mins<1?'Just now':mins<60?mins+'m ago':mins<1440?Math.floor(mins/60)+'h ago':Math.floor(mins/1440)+'d ago'};
const liquidityOf=t=>t.usdcLiquidity??null;
function candlePreview(t){return '<div class="draft-chart">'+(t.status==='live'?'USDC POOL':'NO MARKET YET')+'<span>Open token for market observations</span></div>'}
render=function(){let list=tokens.filter(t=>(view!=='watchlist'||saved.includes(t.id))&&(filter==='all'||t.status===filter)&&(`${t.name} ${t.ticker}`).toLowerCase().includes($('#search').value.toLowerCase()));const sort=$('#sort').value;if(sort==='cap'||sort==='volume')list.sort((a,b)=>b[sort]-a[sort]);if(sort==='new')list.sort((a,b)=>b.id-a.id);$('#marketTitle').innerHTML=`${view==='watchlist'?'Your watchlist':'Discover tokens'}<span class="count">${list.length}</span>`;$('#grid').innerHTML=list.length?list.map(t=>`<article class="token pixel-market-card" tabindex="0" role="button" aria-label="Open ${esc(t.name)} token page" data-id="${t.id}"><div class="pixel-card-inner">
<div class="token-top"><div class="avatar">${profileAvatar(t)}</div><div><h3>${esc(t.name)}</h3><span class="ticker">${esc(t.ticker)} / USDC</span></div><button class="star ${saved.includes(t.id)?'saved':''}" data-save="${t.id}" aria-label="${saved.includes(t.id)?'Remove from':'Add to'} watchlist" aria-pressed="${saved.includes(t.id)}">${saved.includes(t.id)?'★':'☆'}</button></div>
<p class="token-desc">${esc(t.desc)}</p>
<div class="token-chart" title="${t.observedAt?'Finalized: '+new Date(t.observedAt*1000).toISOString():''}">${candlePreview(t)}</div>
<div class="token-stats"><div><span>Market cap</span><b>${t.marketDataAvailable?fmt(t.cap):'—'}</b></div><div><span>USDC liquidity</span><b>${liquidityOf(t)===null?'—':cardUnits(liquidityOf(t))}</b></div><div><span>24h volume</span><b>${t.marketDataAvailable&&t.volume!=null?(t.volumePartial?'≥ ':'')+cardUnits(t.volume):(t.mint?'Indexing':'—')}</b></div></div>
<div class="token-meta"><span class="${t.status==='live'?'live':''}">${t.status==='live'?'● Live':'○ Pre-launch'}</span><span>${mintAge(t)}</span></div>
</div></article>`).join(''):'<div class="empty">No matching tokens. Try another search or filter.</div>';$$('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=Number(b.dataset.save);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write('bluemint-watch',saved);render()});$$('.token').forEach(el=>{el.onclick=()=>detail(Number(el.dataset.id));el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click()}}})};$('#search').oninput=render;$('#sort').onchange=render;
let launchPfp='';function openCreate(){navigate('/launch')}$('#launch').onclick=openCreate;$('#launchBottom').onclick=openCreate;
function showCreate(){if(chartObserver){chartObserver.disconnect();chartObserver=null}homeMain.hidden=true;detailMain.hidden=false;document.title='Create Launch — BlueMint';launchPfp='';detailMain.innerHTML=`<div class="token-breadcrumb"><a href="/">← Discover</a><span>/</span><span>Create launch</span><span class="network-pill">SOLANA MAINNET</span></div><div class="create-heading"><div><span class="eyebrow blue">YOUR TOKEN STARTS HERE</span><h1>Create your launch.</h1><p>Give your token an identity. Build its market in USDC.</p></div><span class="create-step">01 / CONFIGURE → 02 / REVIEW → 03 / SAVE</span></div><div class="create-layout"><form id="createForm" class="create-form"><section class="form-section"><h2><span>01</span> Token identity</h2><label class="pfp-upload" for="pfpFile"><span id="pfpPreview">＋</span><span><b>Upload token PFP</b><small>PNG, JPG or WebP · max 256 KB<br>Square image recommended</small></span><input id="pfpFile" type="file" accept="image/png,image/jpeg,image/webp" required></label><p id="pfpError" class="field-error" role="alert"></p><div class="form-grid"><label class="field">Token name<input name="name" maxlength="32" placeholder="e.g. Blue Hour" required></label><label class="field">Ticker<input name="ticker" maxlength="10" pattern="[A-Za-z0-9]{2,10}" placeholder="e.g. HOUR" required></label></div><label class="field">Description<textarea name="desc" maxlength="160" placeholder="Tell the world what you’re launching." required></textarea></label></section><section class="form-section"><h2><span>02</span> Official links</h2><p class="form-help">These links will be attached to this token’s page when you save. These identity fields cannot be edited after saving.</p><label class="field">Twitter / X link <small>Optional</small><input name="twitter" type="url" placeholder="https://x.com/yourtoken"></label><label class="field">Website link <small>Optional</small><input name="website" type="url" placeholder="https://yourtoken.com"></label><div class="identity-lock">▣ Identity pinned to the saved token page.<span>Saving pins your public profile. On-chain metadata is created in the mint transaction.</span></div></section><section class="form-section"><h2><span>03</span> USDC market & fees</h2><div class="form-grid"><label class="field">Quote asset<input value="Circle USDC · Solana" readonly></label></div><div class="split"><span>Developer buy → liquidity</span><b>50% of developer budget</b></div><div class="split"><span>Launchpad treasury</span><b>0.50%</b></div><div class="split"><span>Token’s Mint allocation</span><b>0.75%</b></div><div class="split"><span>Total launchpad fee</span><b>1.25% + Raydium fees</b></div><p class="form-help">50% of the developer’s USDC buy amount is allocated to this token’s liquidity. No separate liquidity commitment. Launch transactions stay disabled until the vault is qualified and deployed; saving a draft moves no funds.</p></section><p id="createError" class="field-error" role="alert"></p><button class="primary full" type="submit">Review launch →</button></form><aside class="create-sidebar"><section class="create-preview"><span class="eyebrow blue">YOUR TOKEN PREVIEW</span><div class="create-preview-top"><div class="avatar" id="liveAvatar">?</div><div><h3 id="liveName">Your token</h3><span id="liveTicker">TICKER / USDC</span></div></div><p id="liveDesc">Your community’s next chapter starts here.</p><div class="draft-chart">AWAITING LAUNCH<span>Candles appear once a market exists</span></div><div class="split"><span>Quote currency</span><b>USDC</b></div><div class="split"><span>Status</span><b>Not minted</b></div></section><section class="create-mint"><div class="mint-panel-heading"><div><span class="eyebrow blue">♜ THE MINT</span><h3>Your liquidity treasury.</h3></div></div><picture><source media="(prefers-reduced-motion: reduce)" srcset="assets/mint-vault.png"><img src="assets/mint-vault.gif" alt="Animated pixel treasury safe receiving USDC coins"></picture><div class="create-mint-copy"><b>50% of developer buy → liquidity</b><p>Plus 60% of net creator-fee receipts, after Raydium’s protocol share. Vault deployment is pending. No holder rewards.</p><span>LIQUIDITY FLOW · ILLUSTRATION</span></div></section></aside></div>`;
const form=$('#createForm');
if(window.BlueMintBackend?.config?.mode==='launchlab'){
  form.querySelector('.form-section:last-of-type').innerHTML='<h2>USDC market & fees</h2><p>Raydium LaunchLab · Circle USDC quote · 1.25% curve platform fee plus Raydium fees. Creators start with zero initial buy.</p>';
  document.querySelector('.create-mint-copy').textContent='Automatic buybacks and liquidity reinvestment are pending.';
}
form.oninput=()=>{$('#liveName').textContent=form.elements.name.value||'Your token';$('#liveTicker').textContent=(form.elements.ticker.value.toUpperCase()||'TICKER')+' / USDC';$('#liveDesc').textContent=form.elements.desc.value||'Your community’s next chapter starts here.'};$('#pfpFile').onchange=async e=>{launchPfp='';const file=e.target.files[0];$('#pfpError').textContent='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>256*1024){$('#pfpError').textContent='Choose a PNG, JPG or WebP under 256 KB.';e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{launchPfp=reader.result;$('#pfpPreview').innerHTML=`<img src="${launchPfp}" alt="Selected profile picture">`;$('#liveAvatar').innerHTML=`<img src="${launchPfp}" alt="Token preview">`};img.onerror=()=>{$('#pfpError').textContent='This image could not be read.';e.target.value=''};img.src=reader.result};reader.readAsDataURL(file)};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),twitter=f.get('twitter').trim(),website=f.get('website').trim();if(!launchPfp){$('#createError').textContent='Upload a valid profile image first.';return}if((twitter&&(!safeLink(twitter)||!['x.com','www.x.com','twitter.com','www.twitter.com'].includes(new URL(twitter).hostname)))||(website&&!safeLink(website))){$('#createError').textContent='Use HTTPS links. The Twitter link must be on x.com or twitter.com.';return}const requestKey=crypto.randomUUID();const values={name:f.get('name').trim(),ticker:f.get('ticker').toUpperCase(),desc:f.get('desc').trim(),twitter:safeLink(twitter),website:safeLink(website),pfp:launchPfp};if(!values.name||!values.desc){$('#createError').textContent='Enter a name and description.';return}open(`<div class="eyebrow blue">REVIEW YOUR LAUNCH</div><h2>${esc(values.name)} <span class="ticker">${esc(values.ticker)}</span></h2><div class="split"><span>Quote</span><b>Circle USDC</b></div><div class="split"><span>Developer buy</span><b>${window.BlueMintBackend?.config?.mode==='launchlab'?'None at creation':'50% to liquidity'}</b></div><div class="split"><span>Launchpad fee</span><b>1.25% + Raydium</b></div><div class="info-box">Save your public token profile, then review the mainnet mint and pool transactions in your wallet. Saving this profile moves no funds.</div>${values.ticker==='USDC'?'<p class="modal-sub">Your token’s USDC ticker does not make it Circle USDC or dollar-pegged.</p>':''}<button id="saveLaunch" class="primary full">Save profile & continue </button>`);$('#saveLaunch').onclick=async()=>{let t={...values,id:Date.now(),symbol:values.ticker[0],art:'linear-gradient(135deg,#448cff,#142d62)',cap:0,volume:0,change:0,progress:0,age:'Draft',status:'draft',createdAt:new Date().toISOString(),profilePinned:true};if(window.BlueMintBackend?.enabled){try{$('#saveLaunch').disabled=true;t=await window.BlueMintBackend.saveLaunch({...values,requestKey});tokens.unshift(t);modal.close();render();navigate(tokenPath(t.id));toast('Launch profile saved to the registry. No token minted.');return}catch(error){$('#saveLaunch').disabled=false;toast(error.message);return}}toast('Launch service unavailable. Please retry when connected.')}}}

const previousRenderPage=renderPage;renderPage=function(t){previousRenderPage(t);if(t.pfp){$('.token-identity .avatar').innerHTML=profileAvatar(t)}const info=document.createElement('div');info.className='token-profile-links';info.innerHTML=`<span>${t.profilePinned?'▣ SAVED IDENTITY':'TOKEN PROFILE'}</span>${safeLink(t.twitter)?`<a href="${esc(safeLink(t.twitter))}" target="_blank" rel="noopener noreferrer">Twitter / X </a>`:''}${safeLink(t.website)?`<a href="${esc(safeLink(t.website))}" target="_blank" rel="noopener noreferrer">Website </a>`:''}${t.mint?`<a href="/token/${encodeURIComponent(t.mint)}">Mint permalink</a>`:''}<span>${t.status==='draft'?'Not minted · no contract address':`Mint: ${esc(t.mint||'Pending')}`}</span>`;$('.token-heading').after(info);if(t.status==='draft'){$('.chart-panel').innerHTML='<div class="empty"><h2>Your market starts at launch.</h2><p>This is a saved draft. No candles, liquidity, trades or mint address exist yet.</p></div>';if(chartObserver){chartObserver.disconnect();chartObserver=null}$('#pagePrice').textContent='Not minted';activity('about')}};
const oldActivity=activity;activity=function(tab){if(selected.status==='draft'&&tab==='trades'){$('#activityContent').innerHTML='<div class="empty">No transactions. This token has not been minted.</div>';return}oldActivity(tab);if(tab==='about'&&selected.profilePinned){$('#activityContent').insertAdjacentHTML('beforeend',`<div class="info-box profile-note">Identity saved ${esc(new Date(selected.createdAt).toLocaleString())}. PFP and official links are attached to this draft. They are not locked on-chain.</div>`)}};
render();if(location.pathname!=='/launch')route();

